/**
 * ADR-0002 — the media distribution takes the apex certificate and zone from `DomainStack` WITHOUT a CloudFormation
 * export lock.
 *
 * Passing `domain.certificate` to `DataStack` by object makes the CDK mint an AUTO-GENERATED
 * `Fn::ImportValue kitchensink-domain-{stage}:ExportsOutputRef…` in `kitchensink-data-{stage}`. CloudFormation refuses
 * to replace or remove an export while another stack imports it, so the certificate (and the stack holding it) could
 * never change again: the export-in-use deadlock. The two stacks are coupled through SSM parameters the domain stack
 * writes instead, which lock nothing, plus an explicit deploy-order dependency.
 *
 * | Requirement                                                              | Test                                    |
 * | ------------------------------------------------------------------------ | --------------------------------------- |
 * | data imports nothing auto-generated from the domain stack                | 'imports no auto-generated export'      |
 * | domain gains no auto-generated output                                    | 'gains no auto-generated output'        |
 * | the distribution still carries the alias + the domain certificate ARN    | 'still serves the alias with the cert'  |
 * | the data stack reads what the domain stack publishes                     | 'publishes the certificate ARN and ...' |
 * | data still deploys after domain                                          | 'deploys the domain stack first'        |
 */
import { Template } from 'aws-cdk-lib/assertions';
import { describe, expect, it } from 'vitest';

import { GlobalStack } from '../lib/platform/GlobalStack.js';
import { TEST_UPLOAD_ORIGINS } from './mediaDeliveryProps.js';
import { testApp } from './testApp.js';

const env = { account: '123456789012', region: 'us-east-1' };

const makeGlobal = (stage: string): GlobalStack =>
    new GlobalStack(testApp(), `Global-${stage}`, {
        env,
        stackName: `kitchensink-global-${stage}`,
        stage,
        alarmsEnabled: true,
        uploadOrigins: TEST_UPLOAD_ORIGINS,
        domainName: 'commise.app',
    });

interface SynthesizedResource {
    readonly Type: string;
    readonly Properties?: Record<string, unknown>;
}

interface SynthesizedTemplate {
    readonly Parameters?: Record<string, { readonly Default?: string }>;
    readonly Resources: Record<string, SynthesizedResource>;
    readonly Outputs?: Record<string, unknown>;
}

interface DistributionConfig {
    readonly Aliases: readonly string[];
    readonly ViewerCertificate: { readonly AcmCertificateArn: { readonly Ref: string } };
}

const jsonOf = (template: Template): SynthesizedTemplate => template.toJSON() as SynthesizedTemplate;

describe.each(['prod', 'sandbox'])('media delivery and the domain stack on %s', (stage) => {
    it('imports nothing from the domain stack, auto-generated export or otherwise', () => {
        const text = JSON.stringify(Template.fromStack(makeGlobal(stage).data).toJSON());

        expect(text).not.toMatch(/kitchensink-domain-/u);
    });

    it('gains no auto-generated output on the domain stack beyond the shared ALB listener certificates', () => {
        const outputs = Object.keys(jsonOf(Template.fromStack(makeGlobal(stage).domain)).Outputs ?? {});
        // `SharedAlbStack` attaches the certificates to its listener by reference, so these predate the media
        // distribution. The trailing hashes are stripped: they are a function of the construct path, not of the contract.
        const autoGenerated = outputs
            .filter((name) => name.startsWith('ExportsOutput'))
            .map((name) => name.replace(/[0-9A-F]{16}$/u, ''))
            .sort();

        expect(autoGenerated).toEqual(
            stage === 'prod'
                ? ['ExportsOutputRefKitchenSinkCertificate', 'ExportsOutputRefKitchenSinkInternalCertificate']
                : ['ExportsOutputRefKitchenSinkCertificate'],
        );
    });

    it('still serves the alias with the domain certificate ARN', () => {
        const data = jsonOf(Template.fromStack(makeGlobal(stage).data));
        const [distribution] = Object.values(data.Resources).filter(
            (resource) => resource.Type === 'AWS::CloudFront::Distribution',
        );
        const config = distribution?.Properties?.['DistributionConfig'] as DistributionConfig;
        const parameter = data.Parameters?.[config.ViewerCertificate.AcmCertificateArn.Ref];

        expect(config.Aliases).toEqual([stage === 'prod' ? 'media.commise.app' : 'media-sandbox.commise.app']);
        expect(parameter?.Default).toBe(`/kitchensink/${stage}/domain/certificate-arn`);
    });

    it('publishes the certificate ARN and the zone id the data stack reads', () => {
        const domain = jsonOf(Template.fromStack(makeGlobal(stage).domain));
        const names = Object.values(domain.Resources)
            .filter((resource) => resource.Type === 'AWS::SSM::Parameter')
            .map((resource) => resource.Properties?.['Name']);

        expect(names).toEqual(
            expect.arrayContaining([
                `/kitchensink/${stage}/domain/certificate-arn`,
                `/kitchensink/${stage}/domain/hosted-zone-id`,
            ]),
        );
    });

    it('deploys the domain stack first, by dependency rather than by reference', () => {
        const global = makeGlobal(stage);

        expect(global.data.dependencies).toContain(global.domain);
    });
});
